-- ---------- consumables.consumable_issue (12 выдач) ----------

-- ---------- consumables.stock_movement (12 движений склада) ----------

-- ---------- reports.users_view (синхронизация снепшота пользователей) ----------
SELECT id, email, full_name, active, updated_at FROM auth.users
ON CONFLICT (user_id) DO UPDATE SET email=EXCLUDED.email, full_name=EXCLUDED.full_name, active=EXCLUDED.active, updated_at=EXCLUDED.updated_at;

-- ---------- reports.residents_view ----------
SELECT r.id, r.user_id, u.full_name, r.kind, r.faculty, r.study_group, r.department, r.room_id, rm.number, r.enrolled_at, r.evicted_at
FROM residents.resident r
JOIN auth.users u ON u.id = r.user_id
LEFT JOIN residents.room rm ON rm.id = r.room_id
ON CONFLICT (resident_id) DO NOTHING;

-- ---------- reports.requests_view ----------
SELECT req.id, req.type, req.status, req.author_id, ua.full_name, req.assignee_id, uas.full_name, req.target_pool, req.room_id, rm.number, req.created_at, req.closed_at,
       CASE WHEN req.closed_at IS NULL THEN NULL ELSE EXTRACT(EPOCH FROM (req.closed_at - req.created_at))::bigint END,
       req.auto_closed
FROM requests.request req
LEFT JOIN auth.users ua ON ua.id = req.author_id
LEFT JOIN auth.users uas ON uas.id = req.assignee_id
LEFT JOIN residents.room rm ON rm.id = req.room_id
ON CONFLICT (request_id) DO NOTHING;

-- ---------- reports.appliances_view ----------
SELECT a.id, a.resident_id, a.user_id, u.full_name, a.room_id, rm.number, a.type, a.brand, a.model, a.power_watts, a.status, a.created_at, a.updated_at
FROM appliances.appliance a
LEFT JOIN auth.users u ON u.id = a.user_id
LEFT JOIN residents.room rm ON rm.id = a.room_id
ON CONFLICT (appliance_id) DO NOTHING;

-- ---------- reports.consumables_view ----------
SELECT ci.id, ci.resident_id, ci.user_id, u.full_name, ci.type_id, ct.name, ci.quantity, ci.status, ci.issued_at, ci.returned_at, ci.return_condition
FROM consumables.consumable_issue ci
LEFT JOIN auth.users u ON u.id = ci.user_id
JOIN consumables.consumable_type ct ON ct.id = ci.type_id
ON CONFLICT (issue_id) DO NOTHING;

COMMIT;

-- ---------- Сводка ----------
SELECT 'auth.users'                     AS table_name, count(*) AS rows FROM auth.users
UNION ALL SELECT 'auth.user_roles',             count(*) FROM auth.user_roles
UNION ALL SELECT 'residents.room',              count(*) FROM residents.room
UNION ALL SELECT 'residents.resident',          count(*) FROM residents.resident
UNION ALL SELECT 'residents.residency_history', count(*) FROM residents.residency_history
UNION ALL SELECT 'residents.inventory_item',    count(*) FROM residents.inventory_item
UNION ALL SELECT 'requests.request',            count(*) FROM requests.request
UNION ALL SELECT 'requests.request_status_history', count(*) FROM requests.request_status_history
UNION ALL SELECT 'requests.request_comment',    count(*) FROM requests.request_comment
UNION ALL SELECT 'requests.request_attachment', count(*) FROM requests.request_attachment
UNION ALL SELECT 'appliances.appliance',        count(*) FROM appliances.appliance
UNION ALL SELECT 'appliances.appliance_history',count(*) FROM appliances.appliance_history
UNION ALL SELECT 'consumables.consumable_type', count(*) FROM consumables.consumable_type
UNION ALL SELECT 'consumables.consumable_issue',count(*) FROM consumables.consumable_issue
UNION ALL SELECT 'consumables.stock_movement',  count(*) FROM consumables.stock_movement
UNION ALL SELECT 'reports.users_view',          count(*) FROM reports.users_view
UNION ALL SELECT 'reports.residents_view',      count(*) FROM reports.residents_view
UNION ALL SELECT 'reports.requests_view',       count(*) FROM reports.requests_view
UNION ALL SELECT 'reports.appliances_view',     count(*) FROM reports.appliances_view
